node --input-type=module -e '
import {readFileSync} from "node:fs";
import {createHash} from "node:crypto";
import {build} from "esbuild";
const startedAt=new Date().toISOString(),base="docs/remediation/evidence/W07.02/";
const read=p=>JSON.parse(readFileSync(p,"utf8")),hash=b=>createHash("sha256").update(b).digest("hex");
const a=read(base+"artifact-v1.json"),g=read(base+"source-inputs-v1.json"),w=read(base+"worker-checks.json");
const digest=hash(JSON.stringify({contract_digest:a.contract_digest,configuration:a.configuration,files:a.files.map(({path,sha256,role})=>({path,sha256,role})).sort((a,b)=>a.path.localeCompare(b.path))}));
const pins=a.files.map(f=>({...f,actual:hash(readFileSync(f.path))}));
const entryPoints=["src/index.ts","src/index.api-boundary.test.ts","src/services/telemetry.boundary.test.ts","src/telemetry.boundary.test.ts","src/content/consent.test.ts"];
const r=await build({entryPoints,bundle:true,write:false,metafile:true,outdir:"/tmp/w0702-unused-esbuild-output",format:"esm",platform:"browser",target:"es2022",packages:"external",conditions:["workerd","worker","browser"],external:["cloudflare:*","node:*"],alias:{path:"node:path","node:os":"unenv/node/os"},logLevel:"silent"});
const inputs=Object.keys(r.metafile.inputs).sort().map(path=>({path,sha256:hash(readFileSync(path))}));
const graphMatches=JSON.stringify(inputs)===JSON.stringify(g.inputs)&&JSON.stringify(entryPoints)===JSON.stringify(g.entryPoints);
const uncovered=inputs.filter(i=>!pins.some(p=>p.path===i.path&&p.sha256===i.sha256));
const originals=JSON.parse(read(base+"baseline.json").output).originalSources.map(({source,...f})=>({...f,actual:hash(source)}));
const outputs=w.freeze.owned.map(f=>({...f,actual:hash(readFileSync(f.path)),pinned:pins.some(p=>p.path===f.path&&p.sha256===f.sha256)}));
const regressions=w.freeze.unchangedRegressionFixtures.map(f=>({...f,actual:hash(readFileSync(f.path))}));
const oldW07=read("docs/remediation/evidence/W07.01/worker-checks.json");
const protectedFiles=[...oldW07.freeze.files,{path:"src/content/service.ts",sha256:"dff26109e9389cacb1f2bfae4db220f926bbaca6b10376023535e46a3b1a2bf8"},{path:"src/content/consent.test.ts",sha256:"83bd9de816cb610913a80e45df44ca32742f566a8281ad0961e991a073f37b09"},{path:"src/routes/config.ts",sha256:"22beb4d906345afee1267a1c146fcaac003490d360a6ab85d5a5c1ee0e551499"},{path:"src/routes/content.ts",sha256:"4344476c6d9d61db58f243f9e6649b499d2ac029269ea4dfa5fccf4447a8eed8"},{path:"src/middleware/auth.ts",sha256:"9b85d4b97e6af7f08c916e2c82c18ebc4e0e3bbd2cf12acb52d00ad2c19dfe01"}].map(f=>({...f,actual:hash(readFileSync(f.path))}));
const proofHashes=["artifact-v1.json","source-inputs-v1.json","baseline-probe.mjs","baseline.json","worker.md","worker-checks.json"].map(name=>({path:base+name,sha256:hash(readFileSync(base+name))}));
const qualifications=["qualify-w34.01-e1-v1.json","qualify-w34.01-e2-v1.json","qualify-w07.01-e1-v1.json","qualify-w07.01-e2-v1.json","qualify-w07.01-e3-v1.json"].map(name=>{const q=read(base+name);return{path:base+name,sha256:hash(readFileSync(base+name)),before:{id:q.before?.id,status:q.before?.status},after:{id:q.after?.id,status:q.after?.status},keys:Object.keys(q)};});
const passed=digest===a.digest&&digest==="49d634e9c23fd2dc9f337009814528445686790ab375ff31ed1fd498854db5c2"&&a.contract_digest==="cad91b6161d2a439e9b870a7edc78f7122887ac8c26626e2481e2d26caa195bf"&&pins.length===181&&new Set(pins.map(p=>p.path)).size===181&&pins.every(p=>p.actual===p.sha256)&&inputs.length===168&&graphMatches&&!uncovered.length&&originals.length===4&&originals.every(p=>p.actual===p.sha256)&&outputs.length===5&&outputs.every(p=>p.actual===p.sha256&&p.pinned)&&regressions.length===3&&regressions.every(p=>p.actual===p.sha256)&&protectedFiles.every(p=>p.actual===p.sha256);
console.log(JSON.stringify({startedAt,completedAt:new Date().toISOString(),passed,digest,pins,graphCommand:g.command,graphMatches,inputs,uncovered,originals,outputs,regressions,protectedFiles,proofHashes,qualifications},null,2));
if(!passed)process.exitCode=1;
'
